"                        {checkPosAccess('KOT', 'visible') && (
                        <button 
                          onClick={() => setActiveTrayTab('KOT')} 
                          className={`py-1 px-3 text-[11px] transition-all rounded border ${
                            activeTrayTab === 'KOT'
                              ? (isDark ? 'bg-[#1b4332] text-[#48c78e] border-[#2d6a4f] font-bold' : 'bg-[#d4edd9] text-[#1c4934] border-[#c3e6cb] font-bold')
                              : (isDark ? 'bg-transparent text-[#8b949e] border-transparent hover:text-white font-bold' : 'bg-transparent text-slate-600 border-transparent hover:bg-slate-50 font-bold')
                          }`}
                        >
                          Order/KOT
                        </button>
                        )}
                        {checkPosAccess('Billing', 'visible') && (
                        <button 
                          onClick={() => setActiveTrayTab('Billing')} 
                          className={`py-1 px-3 text-[11px] transition-all rounded border ${
                            activeTrayTab === 'Billing'
                              ? (isDark ? 'bg-[#1b4332] text-[#48c78e] border-[#2d6a4f] font-bold' : 'bg-[#d4edd9] text-[#1c4934] border-[#c3e6cb] font-bold')
                              : (isDark ? 'bg-transparent text-[#8b949e] border-transparent hover:text-white font-bold' : 'bg-transparent text-slate-600 border-transparent hover:bg-slate-50 font-bold')
                          }`}
                        >
                          Billing
                        </button>
                        )}"

